CREATE TABLE outreach_sequences (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, name TEXT NOT NULL, purpose TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', business_timezone TEXT NOT NULL DEFAULT 'Asia/Kolkata', max_attempts INTEGER NOT NULL DEFAULT 1, created_by_id TEXT NOT NULL, approved_by_id TEXT, approved_at TIMESTAMP, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outreach_steps (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, sequence_id TEXT NOT NULL REFERENCES outreach_sequences(id), step_order INTEGER NOT NULL, delay_business_days INTEGER NOT NULL CHECK(delay_business_days BETWEEN 1 AND 14), subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'draft', UNIQUE(organization_id,sequence_id,step_order));
CREATE TABLE sequence_enrollments (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, sequence_id TEXT NOT NULL REFERENCES outreach_sequences(id), thread_id TEXT NOT NULL REFERENCES outreach_threads(id), status TEXT NOT NULL DEFAULT 'scheduled', current_step INTEGER NOT NULL DEFAULT 1, attempts INTEGER NOT NULL DEFAULT 0, next_run_at TIMESTAMP, stop_reason TEXT, stopped_at TIMESTAMP, created_by_id TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX sequence_enrollments_org_due_idx ON sequence_enrollments(organization_id,status,next_run_at);
CREATE TABLE pipeline_handoff_snapshots (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, application_id TEXT NOT NULL, candidate_id TEXT NOT NULL, position_id TEXT NOT NULL, shortlist_decision_id TEXT NOT NULL, candidate_evaluation_id TEXT NOT NULL, rubric_id TEXT NOT NULL, rubric_version INTEGER NOT NULL, evidence_snapshot JSON NOT NULL, response_thread_id TEXT NOT NULL, rationale TEXT NOT NULL, advanced_by_id TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pipeline_stage_transitions (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, application_id TEXT NOT NULL, from_stage TEXT NOT NULL, to_stage TEXT NOT NULL, actor_user_id TEXT NOT NULL, rationale TEXT NOT NULL, snapshot_id TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX pipeline_stage_transitions_org_app_idx ON pipeline_stage_transitions(organization_id,application_id,created_at);
